#include <Servo.h>

Servo myservo;

const int servoPin = 14;

void setup() {
  myservo.attach(servoPin, 500, 2400); 
}

void loop() {
  for (int pos = 0; pos <= 180; pos += 1) {
    myservo.write(pos);
    delay(15);
  }
  delay(1000); 
  for (int pos = 180; pos >= 0; pos -= 1) {
    myservo.write(pos);
    delay(15);
  }
  delay(1000); 
}
